UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Account" :  {
        "Payer": "   WITH _data AS ( SELECT dttrxntime, vcmsgid, observations, vcpayeraccountexternalid, vcpayeeaccountexternalid, vcpayeraddr, vcpayeeaddr, risk_context, vcuniquetransid, vctxnfield1, vctxnfield2, vctxnfield3,vctxnfield4 FROM t14refined.analytics.trans l WHERE tdate between :StartDate  and :EndDate ), _filtered_data AS ( SELECT * FROM _data WHERE ( vcpayeraccountexternalid = :VpaAddress) LIMIT 50000 ) SELECT  json_extract_scalar( risk_context, ''$.attribs[0].referenceNumber'') AS \\"Post-Auth RRN\\", JSON_EXTRACT_SCALAR(risk_context, ''$.attribs[0].failureCode'') AS \\"Failure Code\\", JSON_EXTRACT_SCALAR(risk_context, ''$.attribs[0].failureMessage'') AS \\"Failure Message\\", json_extract_scalar(observations, ''$.txn.attribs.method.typeNarration'') AS \\"Type Description\\", json_extract_scalar(observations, ''$.txn.attribs.method.subtypeNarration'') AS \\"Sub-Type Description\\", CASE WHEN try(cast(json_extract(observations, ''$.txn.type'') AS array(json))) IS NOT NULL THEN cast( element_at( cast(json_extract(observations, ''$.txn.type'') AS array(json)), cardinality(cast(json_extract(observations, ''$.txn.type'') AS array(json))) ) AS varchar ) ELSE json_extract_scalar(observations, ''$.txn.type'') END AS \\"Txn Type\\", json_extract_scalar(observations, ''$.txn.attribs.referenceNumber'') AS \\"RRN\\", json_extract_scalar(observations, ''$.txn.id'') AS \\"Txn id\\", json_extract_scalar(observations, ''$.txn.ts'') AS \\"Timestamp\\", json_extract_scalar(observations, ''$.txn.attribs.initator.customerId'') AS \\"Initiator User ID\\", json_extract_scalar(observations, ''$.payee.attribs.address.countryCode'') AS \\"Payee Address Country Code\\", json_extract_scalar(observations, ''$.txn.attribs.captureMethod'') AS \\"Capture Method\\", json_extract_scalar(observations, ''$.txn.attribs.mode'') AS \\"Mode\\", json_extract_scalar(observations, ''$.txn.attribs.method.type'') AS \\"Type\\", json_extract_scalar(observations, ''$.txn.attribs.method.subType'